const names=['Overview','Concept & interaction','Context & research','Audience & space','Structure & materials','Technical system','Exhibition & reflection'];
export const tremulantChapters=names.map((name,i)=>[name,'tremulant-'+i]);
const photo=(image,cls='')=>`<img class="${cls}" src="${image.preview||image.src}" alt="Tremulant Oracles installation" loading="lazy" decoding="async" width="${image.width}" height="${image.height}">`;
// A viewport reuses only the desired visual fragment; English remains native text.
const fragment=(image,x,y,w,h,cls='')=>`<div class="to-fragment ${cls}" style="aspect-ratio:${w*image.width}/${h*image.height}"><img src="${image.preview||image.src}" alt="Original project diagram" loading="lazy" decoding="async" style="width:${100/w}%;left:${-x/w*100}%;top:${-y/h*100}%;height:auto"></div>`;
const heading=(label,title)=>`<span class="to-eyebrow">${label}</span><h2>${title}</h2>`;
function matrix(step=0){return `<svg class="to-magnet-grid" viewBox="0 0 160 160" role="img" aria-label="Five by five electromagnet array"><rect x="1" y="1" width="158" height="158" rx="13" fill="none" stroke="currentColor"/>${Array.from({length:25},(_,i)=>`<circle cx="${16+i%5*32}" cy="${16+Math.floor(i/5)*32}" r="12" fill="${step&&i%4!==step-1?'#555':'currentColor'}"/>`).join('')}</svg>`;}
export function createTremulantProject(article,project,openImage){
 article.classList.add('tremulant-article');
 const images=project.images,boards=images.filter(i=>/^portfolio/i.test(i.name)),photos=images.filter(i=>!/^portfolio/i.test(i.name));
 const content=[
  `<div class="to-cover-image">${photo(photos[1])}</div><div class="to-cover-copy"><span class="to-number">01</span><p class="to-eyebrow">INTERACTIVE INSTALLATION / 2025</p><h1>Tremulant<br>Oracles</h1><p class="to-cover-tagline">A question. A trembling answer.<br>A machine performing belief.</p><div class="to-tags"><span>Artificial intelligence</span><span>Ferrofluid</span><span>Ritual & interaction</span></div><div class="to-credits"><strong>Collaborative work</strong><p>My role<br>Creative planning · Art direction<br>Interaction design · Technical implementation</p><p>April–May 2025</p></div></div>`,
  `<div class="to-concept-top">${heading('01 / CONCEPT','An oracle that reveals its own illusion.')}<p>A transparent cube holds a contemporary wishing pool. Visitors ask a question; AI interprets it, and ferrofluid gives the machine a physical voice.</p><blockquote>We know the oracle is artificial.<br>Why do we still wait for its answer?</blockquote></div><div class="to-concept-flow"><span class="to-eyebrow">THE INTERACTION</span><div class="to-steps">${[['01','Read','Encounter the instructions and the ritual.'],['02','Record','Hold the button while asking a question.'],['03','Interpret','Speech recognition and AI produce a yes/no result.'],['04','Translate','Arduino turns the result into magnetic control.'],['05','Respond','Ferrofluid moves—or remains still.']].map(([n,t,p])=>`<div><span class="to-step-no">${n}</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></div>`,
  `<div class="to-history to-light">${heading('02 / CONTEXT','From divination<br>to digital belief.')}<ol>${[['Print & ritual','Fortune books, lots and face-to-face divination.'],['Telephone & web','Hotlines and websites turn consultation into a mediated service.'],['Social platforms','Short videos, livestreams and paid readings bring belief into everyday feeds.'],['AI interfaces','Language models add a conversational, personalised voice to the oracle.']].map(([a,b])=>`<li><h3>${a}</h3><p>${b}</p></li>`).join('')}</ol></div><div class="to-research">${heading('EXPLORATORY PROJECT RESEARCH','Who listens to<br>an AI oracle?')}<div class="to-stat-row"><div><b>149</b><span>survey & interview responses</span></div><div><b>72</b><span>women</span></div><div><b>77</b><span>men</span></div></div><p>The original research combined an electronic questionnaire with interviews, looking at divination platforms, user profiles and awareness of AI technologies.</p><h3>What participants associated with AI divination</h3><div class="to-research-bars">${[['41','Model training & personalised prediction'],['58','Interaction: voice, virtual characters & AI interpretation'],['1','Visualisation: divination in 3D']].map(([n,t])=>`<div><span>${t}</span><strong>${n}%</strong><i style="--bar:${n}%"></i></div>`).join('')}</div></div>`,
  `<div class="to-audience">${heading('03 / AUDIENCE','Two ways into the ritual.')}<div class="to-personas"><div>${fragment(boards[3],.034,.225,.057,.21)}<h3>The curious participant</h3><p>Drawn to digital art, immersive environments and symbolic experiences. Wants to test an unfamiliar ritual while retaining a critical distance.</p><span>Curiosity · Experience · Self-reflection</span></div><div>${fragment(boards[3],.227,.225,.057,.21)}<h3>The technically aware visitor</h3><p>Interested in how algorithms and interactive systems work. Recognises the mechanism, yet still takes part in the performance of an answer.</p><span>Technology · Interpretation · Participation</span></div></div><p class="to-note">Audience profiles developed in the original design research.</p></div><div class="to-space">${heading('SPATIAL ARRANGEMENT','A small object.<br>A shared atmosphere.')}<svg viewBox="0 0 460 370" role="img" aria-label="Four metre square room with a 35 centimetre installation at its centre"><g fill="none" stroke="currentColor"><rect x="60" y="35" width="310" height="310"/><path d="M60 35L370 345M370 35L60 345" stroke-dasharray="4 5" opacity=".3"/><rect x="201" y="176" width="28" height="28"/><path d="M60 19H370M44 35V345"/></g><g fill="currentColor" font-family="Arial" font-size="13"><text x="192" y="13">4 m</text><text x="10" y="195">4 m</text><text x="178" y="227">35 × 35 cm</text><text x="163" y="250">Installation</text><text x="282" y="62">Projector</text></g><rect x="326" y="40" width="35" height="18" fill="#aaa"/></svg><div class="to-tags"><span>AI as a false god</span><span>A pool as ritual symbol</span><span>Knowing participation</span><span>Critique of technomysticism</span></div></div>`,
  `<div class="to-critical">${heading('04 / CRITICAL POSITION','How does a machine<br>become an authority?')}<p>The work exposes the construction of algorithmic divinity: a statistical process is staged as an apparently sacred response.</p><blockquote>Rational tools.<br>Irrational belief.<br><em>A shared illusion.</em></blockquote><p>The trembling liquid reveals the magnets and electronics beneath the pool. The revelation does not end the ritual—it becomes part of it.</p></div><div class="to-materials">${photo(photos[0])}<div class="to-material-label">STRUCTURE & MATERIALS</div><ol><li><b>01 / The pool</b><span>Transparent acrylic enclosure, water and ferrofluid.</span></li><li><b>02 / Magnetic system</b><span>Electromagnets, MOSFET switching and Arduino control.</span></li><li><b>03 / The pedestal</b><span>Aluminium structure and acrylic panels, lit from within.</span></li><li><b>04 / Atmosphere</b><span>Projected water patterns and a written interaction guide.</span></li></ol></div>`,
  `<div class="to-technical">${heading('05 / TECHNICAL SYSTEM','From spoken language<br>to a magnetic field.')}<div class="to-tech-flow"><span>Microphone</span><i>→</i><span>Speech + AI</span><i>→</i><span>Arduino</span><i>→</i><span>MOSFETs</span><i>→</i><span>Ferrofluid</span></div><p>Speech recognition and semantic interpretation produce a binary decision. This result is sent to the Arduino, which switches the electromagnets through MOSFET modules.</p><div class="to-hardware"><span><b>25</b> electromagnets</span><span><b>2 × 12 V</b> external supplies</span><span><b>5 × 5</b> magnetic array</span></div><div class="to-response"><div>${matrix()}<h3>Resting state</h3><p>The magnetic array holds the liquid in a stable state.</p></div><div>${matrix(2)}<h3>Moving response</h3><p>Groups of magnets activate in sequence, translating an answer into physical motion.</p></div></div></div><div class="to-circuit to-light">${heading('HARDWARE','Circuit layout')}${fragment(boards[5],.675,.17,.31,.74)}<p>Arduino · MOSFET drivers · 25 electromagnets<br>Two external 12 V power supplies</p></div>`,
  `<div class="to-exhibition to-light">${heading('06 / ENCOUNTER','A ritual performed together.')}<div class="to-six-photos">${photos.slice(0,6).map(i=>photo(i)).join('')}</div></div><div class="to-reflection">${heading('REFLECTION','The answer is made.<br>The belief is real.')}<h3>The paradox of rational mysticism</h3><p>Precise technical systems are used to simulate divination. The installation asks how technological rationality and mystical belief can reinforce each other.</p><h3>Where does the aura reside?</h3><p>The fluid is driven by statistical interpretation and electromagnetic control. What visitors experience as an oracle may also be their own desire for meaning.</p><h3>Questioning the divination economy</h3><p>Uncertainty becomes data; attention and anticipation become part of an exchange. By revealing the mechanism, the work opens this exchange to scrutiny.</p></div>`
 ];
 content.forEach((html,i)=>{const section=document.createElement('section');section.className='to-board to-page-'+i;section.id='tremulant-'+i;section.setAttribute('aria-label',names[i]);section.innerHTML=html;const footer=document.createElement('footer');footer.className='to-board-footer';footer.textContent=`TREMULANT ORACLES / 2025     —     ${String(i+1).padStart(2,'0')} / 07`;section.append(footer);article.append(section);});
 const archive=document.createElement('section');archive.className='to-photo-archive';archive.id='tremulant-photos';
 for(const [i,item] of photos.entries()){const button=document.createElement('button');button.type='button';button.setAttribute('aria-label','Enlarge installation photograph '+(i+1));button.innerHTML=photo(item);button.onclick=()=>openImage(photos,i,project.title);archive.append(button);}article.append(archive);
}
